//! JavaScript bindings for the Lineage engine.
//!
//! Every document operation crosses this boundary as bytes in, bytes out. TypeScript
//! never parses document XML. Phase 0 exposes only enough to prove the bridge: a
//! string going out and a byte buffer going both ways.
//!
//! No `forbid(unsafe_code)` here: code generated by `#[wasm_bindgen]` uses `unsafe`.

use wasm_bindgen::prelude::wasm_bindgen;

/// The engine version, so the shell can check it loaded the build it expects.
#[wasm_bindgen(js_name = engineVersion)]
#[must_use]
pub fn engine_version() -> String {
    lineage::ENGINE_VERSION.to_owned()
}

/// Returns a copy of the bytes it was given. Proves that `Uint8Array` crosses the
/// boundary in both directions without being altered.
#[wasm_bindgen(js_name = echoBytes)]
#[must_use]
pub fn echo_bytes(bytes: &[u8]) -> Vec<u8> {
    bytes.to_vec()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn engine_version_matches_crate() {
        assert_eq!(engine_version(), env!("CARGO_PKG_VERSION"));
    }

    #[test]
    fn echo_bytes_round_trips() {
        let all_values: Vec<u8> = (0..=u8::MAX).collect();
        assert_eq!(echo_bytes(&all_values), all_values);
        assert!(echo_bytes(&[]).is_empty());
    }
}
